'use client';

import * as React from 'react';

// @interlace/note-board v1.0.0 — Interlace design system.
// Docs, props and live preview: https://ds.interlace.tools/c/note-board
// What changed since: https://ds.interlace.tools/c/note-board#history
// Generated banner — keep it, the upgrade diff reads this version.

/**
 * @interlace/ui — NoteBoard
 *
 * A shared board of sticky notes in columns: a retrospective ("Keep /
 * Change / Try"), an affinity sort, a "before / during / after" map.
 * People post a note into a column, and the room sorts them by moving
 * notes between columns. Every screen folds the same posts and moves with
 * `foldBoard`, so the board agrees everywhere.
 *
 * Moving is a pair of buttons on each note, named for the column they move
 * it to (arrows that point across when the columns sit side by side, and up
 * and down when they stack), so a note moves the same way by touch, mouse, keyboard or screen
 * reader, and focus stays on the note that moved.
 *
 * ## Anatomy
 *
 *   NoteBoard                      (div — data-slot="note-board", @container)
 *     └─ FlipGroup                 (data-slot="note-board-columns": the columns side by side, or stacked)
 *         └─ section × n           (data-slot="note-board-column", named by its title)
 *             ├─ header            (title, count)
 *             ├─ ul                (data-slot="note-board-notes")
 *             │   └─ li × n        (data-slot="note-board-note", data-flip-id: text, move buttons)
 *             └─ form              (data-slot="note-board-add": when `onAdd`; field, Add, why not)
 *     └─ span sr-only aria-live    (data-slot="note-board-announce": "Moved to Try.")
 *
 * ## Motion
 *
 * A note that moves glides from its old column to its new place, and the
 * notes around it close up (FlipGroup, 250ms, `ease-move`). A new note
 * fades in. Under reduced motion every note simply takes its place.
 *
 * ## MIN_VIEWPORT — 320
 *
 * | Rule | Concept                   | Where in this file                                   |
 * | ---- | ------------------------- | ---------------------------------------------------- |
 * | R4   | Extends native el         | `div` props                                          |
 * | R6   | data-slot per part        | note-board / -columns / -column / -notes / -note / -add / -announce |
 * | R7   | cn + ...rest              | `cn(…, className)` + `{...props}`                    |
 * | R8   | Enums, not booleans       | `size`                                               |
 * | R14  | Declares min viewport     | `data-min-viewport` + exported const                 |
 * | R26  | A11y                      | named columns; move buttons name their column; focus follows the note; moves announced |
 */

import { ArrowDown, ArrowLeft, ArrowRight, ArrowUp } from 'lucide-react';

import { FlipGroup } from '@/components/ui/effects/flip-group';
import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { foldBoard, type BoardMove, type BoardNote } from '@/components/ui/games/note-board-model';
import { checkText, type TextRefusal } from '@/components/ui/games/text-safety-model';

export const MIN_VIEWPORT = 320 as const;

interface NoteBoardColumn {
  id: string;
  title: string;
}

interface NoteBoardLabels {
  /** @default (column) => `Move to ${column}` */
  move?: (column: string) => string;
  /** @default (column) => `Moved to ${column}.` */
  moved?: (column: string) => string;
  /** The add field's name. @default (column) => `Add a note to ${column}` */
  field?: (column: string) => string;
  /** @default 'Add' */
  add?: string;
  /** In the empty add field. @default 'Add a note' */
  placeholder?: string;
  /** A column with no notes yet. @default 'No notes yet.' */
  empty?: string;
  /** @default (n) => `${n} notes` */
  count?: (n: number, formatted: string) => string;
  /** Why a note was not added. */
  refused?: Partial<Record<TextRefusal, string>>;
}

type NoteBoardProps = Omit<React.ComponentProps<'div'>, 'children'> & {
  columns: readonly NoteBoardColumn[];
  notes: readonly BoardNote[];
  moves?: readonly BoardMove[];
  /** Let the viewer move notes. Moves show at once and are sent here. */
  onMove?: (move: BoardMove) => void;
  /** Let the viewer post a note into a column, after the room's text checks. */
  onAdd?: (column: string, text: string) => void;
  /** Words the room refuses in a new note. */
  blocklist?: readonly string[];
  /** @default 140 */
  maxLength?: number;
  /** `stage` for a shared screen. @default 'default' */
  size?: 'default' | 'stage';
  locale?: string;
  labels?: NoteBoardLabels;
};

const REFUSED: Record<TextRefusal, string> = {
  empty: 'Type a note first.',
  'too-long': 'That is too long for a note. Try a shorter one.',
  'too-many-words': 'That is too long for a note. Try a shorter one.',
  link: 'Links cannot go on the board.',
  contact: 'Email addresses and phone numbers cannot go on the board.',
  blocked: 'That note cannot go on the board. Try other words.',
};

function AddNote({
  column,
  title,
  onAdd,
  blocklist,
  maxLength,
  labels,
}: {
  column: string;
  title: string;
  onAdd: (column: string, text: string) => void;
  blocklist?: readonly string[];
  maxLength: number;
  labels?: NoteBoardLabels;
}) {
  const [value, setValue] = React.useState('');
  const [refused, setRefused] = React.useState<TextRefusal | null>(null);
  const messageId = React.useId();
  return (
    <form
      data-slot="note-board-add"
      noValidate
      className="grid gap-1"
      onSubmit={(e) => {
        e.preventDefault();
        const check = checkText(value, { maxLength, blocklist });
        if (!check.ok) {
          setRefused(check.reason);
          return;
        }
        setRefused(null);
        setValue('');
        onAdd(column, check.text);
      }}
    >
      <div className="flex gap-2">
        <Input
          value={value}
          aria-label={(labels?.field ?? ((c: string) => `Add a note to ${c}`))(title)}
          placeholder={labels?.placeholder ?? 'Add a note'}
          aria-invalid={refused ? true : undefined}
          aria-describedby={messageId}
          onChange={(e) => {
            setValue(e.target.value);
            if (refused) setRefused(null);
          }}
          className="min-w-0 flex-1"
        />
        <Button type="submit" variant="outline">
          {labels?.add ?? 'Add'}
        </Button>
      </div>
      <p id={messageId} aria-live="polite" className="text-destructive text-xs empty:hidden">
        {refused ? (labels?.refused?.[refused] ?? REFUSED[refused]) : ''}
      </p>
    </form>
  );
}

function NoteBoard({
  columns,
  notes,
  moves = [],
  onMove,
  onAdd,
  blocklist,
  maxLength = 140,
  size = 'default',
  locale,
  labels,
  className,
  style,
  ...props
}: NoteBoardProps) {
  const nf = React.useMemo(() => new Intl.NumberFormat(locale), [locale]);
  const [own, setOwn] = React.useState<BoardMove[]>([]);
  const [announce, setAnnounce] = React.useState('');
  const focusNext = React.useRef<{ id: string; dir: -1 | 1 } | null>(null);
  const rootRef = React.useRef<HTMLDivElement>(null);
  const ids = columns.map((c) => c.id);
  const board = foldBoard(ids, notes, [...moves, ...own]);
  const titleOf = (id: string) => columns.find((c) => c.id === id)?.title ?? id;
  const stage = size === 'stage';

  // Keep focus on the note that moved: the same arrow if it can go further, else the other one.
  React.useLayoutEffect(() => {
    const next = focusNext.current;
    focusNext.current = null;
    if (!next) return;
    const note = Array.from(rootRef.current?.querySelectorAll<HTMLElement>('[data-slot="note-board-note"]') ?? []).find(
      (el) => el.dataset.flipId === next.id,
    );
    const same = note?.querySelector<HTMLButtonElement>(`[data-move="${next.dir}"]`);
    const other = note?.querySelector<HTMLButtonElement>(`[data-move="${-next.dir}"]`);
    (same ?? other ?? note)?.focus();
  });

  const move = (note: BoardNote, to: number, dir: -1 | 1) => {
    const column = ids[to] as string;
    const m: BoardMove = { id: note.id, column, at: Math.max(Date.now(), note.at) };
    setOwn((list) => [...list.filter((x) => x.id !== note.id), m]);
    focusNext.current = { id: note.id, dir };
    setAnnounce((labels?.moved ?? ((c: string) => `Moved to ${c}.`))(titleOf(column)));
    onMove?.(m);
  };

  return (
    <div
      ref={rootRef}
      data-slot="note-board"
      data-min-viewport={String(MIN_VIEWPORT)}
      className={cn('@container', className)}
      style={{ '--note-board-cols': String(Math.max(1, columns.length)), ...style } as React.CSSProperties}
      {...props}
    >
      <FlipGroup
        duration={250}
        data-slot="note-board-columns"
        className="grid gap-4 @3xl:grid-cols-[repeat(var(--note-board-cols),minmax(0,1fr))]"
      >
        {board.map((col, ci) => {
          const title = titleOf(col.id);
          const headingId = `note-board-${col.id}`;
          return (
            <section
              key={col.id}
              data-slot="note-board-column"
              aria-labelledby={headingId}
              className="bg-muted/50 grid content-start gap-3 rounded-xl border p-3"
            >
              <header className="flex items-baseline justify-between gap-2 px-1">
                <h3 id={headingId} className={cn('font-heading font-semibold', stage ? 'text-xl' : 'text-base')}>
                  {title}
                </h3>
                <span className="text-muted-foreground text-xs tabular-nums">
                  {(labels?.count ?? ((n: number, f: string) => `${f} ${n === 1 ? 'note' : 'notes'}`))(
                    col.notes.length,
                    nf.format(col.notes.length),
                  )}
                </span>
              </header>
              {col.notes.length === 0 ? (
                <p className="text-muted-foreground px-1 text-sm">{labels?.empty ?? 'No notes yet.'}</p>
              ) : (
                <ul data-slot="note-board-notes" className="grid gap-2">
                  {col.notes.map((note) => (
                    <li
                      key={note.id}
                      data-slot="note-board-note"
                      data-flip-id={note.id}
                      tabIndex={-1}
                      className={cn(
                        'bg-card focus-visible:outline-ring flex items-start gap-2 rounded-lg border p-3 shadow-xs outline-offset-2 focus-visible:outline-2',
                        stage ? 'text-lg' : 'text-sm',
                      )}
                    >
                      <span className="min-w-0 flex-1 text-pretty">{note.text}</span>
                      {onMove ? (
                        <span className="-my-1 -me-1 flex shrink-0">
                          {ci > 0 ? (
                            <Button
                              type="button"
                              variant="ghost"
                              size="icon-sm"
                              data-move="-1"
                              aria-label={(labels?.move ?? ((c: string) => `Move to ${c}`))(
                                titleOf(ids[ci - 1] as string),
                              )}
                              title={titleOf(ids[ci - 1] as string)}
                              onClick={() => move(note, ci - 1, -1)}
                            >
                              <ArrowUp aria-hidden className="@3xl:hidden" />
                              <ArrowLeft aria-hidden className="hidden rtl:rotate-180 @3xl:block" />
                            </Button>
                          ) : null}
                          {ci < board.length - 1 ? (
                            <Button
                              type="button"
                              variant="ghost"
                              size="icon-sm"
                              data-move="1"
                              aria-label={(labels?.move ?? ((c: string) => `Move to ${c}`))(
                                titleOf(ids[ci + 1] as string),
                              )}
                              title={titleOf(ids[ci + 1] as string)}
                              onClick={() => move(note, ci + 1, 1)}
                            >
                              <ArrowDown aria-hidden className="@3xl:hidden" />
                              <ArrowRight aria-hidden className="hidden rtl:rotate-180 @3xl:block" />
                            </Button>
                          ) : null}
                        </span>
                      ) : null}
                    </li>
                  ))}
                </ul>
              )}
              {onAdd ? (
                <AddNote
                  column={col.id}
                  title={title}
                  onAdd={onAdd}
                  blocklist={blocklist}
                  maxLength={maxLength}
                  labels={labels}
                />
              ) : null}
            </section>
          );
        })}
      </FlipGroup>
      <span data-slot="note-board-announce" aria-live="polite" className="sr-only">
        {announce}
      </span>
    </div>
  );
}
NoteBoard.displayName = 'NoteBoard';

export { NoteBoard };
export type { NoteBoardProps, NoteBoardLabels, NoteBoardColumn };

export interface BoardNote {
  id: string;
  column: string;
  text: string;
  /** When it was posted, in ms. */
  at: number;
}

export interface BoardMove {
  /** The note moved. */
  id: string;
  /** The column it moved to. */
  column: string;
  /** When, in ms. */
  at: number;
}

export interface BoardColumn {
  id: string;
  notes: BoardNote[];
}

const byPost = (a: BoardNote, b: BoardNote) => a.at - b.at || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0);

export function foldBoard(
  columnIds: readonly string[],
  notes: readonly BoardNote[],
  moves: readonly BoardMove[] = [],
): BoardColumn[] {
  const rank = new Map(columnIds.map((id, i) => [id, i]));
  const first = new Map<string, BoardNote>();
  for (const n of notes) {
    if (!n || !rank.has(n.column) || !Number.isFinite(n.at)) continue;
    const had = first.get(n.id);
    if (!had || byPost(n, had) < 0) first.set(n.id, n);
  }
  const latest = new Map<string, BoardMove>();
  for (const m of moves) {
    if (!m || !rank.has(m.column) || !Number.isFinite(m.at)) continue;
    const had = latest.get(m.id);
    const later =
      !had || m.at > had.at || (m.at === had.at && (rank.get(m.column) as number) > (rank.get(had.column) as number));
    if (later) latest.set(m.id, m);
  }
  const out = new Map(columnIds.map((id) => [id, [] as BoardNote[]]));
  for (const n of first.values()) {
    const move = latest.get(n.id);
    const column = move && move.at >= n.at ? move.column : n.column;
    out.get(column)?.push(column === n.column ? n : { ...n, column });
  }
  return [...out].map(([id, list]) => ({ id, notes: list.sort(byPost) }));
}

/**
 * @interlace/ui — note-board-model
 *
 * A board of sticky notes in columns: a retrospective ("Keep / Change /
 * Try"), an affinity sort, a "before / during / after" map. People post
 * notes into a column, and notes are moved as the room sorts them.
 *
 * The board is folded from two streams of events: notes posted and moves.
 * Each note sits in the column of its latest move (by time; on the same
 * time, the column listed later wins), so every screen agrees whatever
 * order the events arrive in and however many times one is delivered. A
 * note posted twice keeps its first posting. A note or move naming a
 * column that does not exist is dropped. Inside a column, notes stay in the
 * order they were posted.
 */

export type TextRefusal = 'empty' | 'too-long' | 'too-many-words' | 'link' | 'contact' | 'blocked';

export interface TextRules {
  /** The most characters, as the reader counts them. @default 200 */
  maxLength?: number;
  /** The most words. @default Infinity */
  maxWords?: number;
  /** Words the room refuses. Matched whole, after `foldText`. */
  blocklist?: readonly string[];
  /** Let links through. @default false */
  allowLinks?: boolean;
  /** Let email addresses and phone numbers through. @default false */
  allowContact?: boolean;
}

export type TextCheck = { ok: true; text: string } | { ok: false; reason: TextRefusal };

const SWAPS: Record<string, string> = { '0': 'o', '1': 'i', '3': 'e', '4': 'a', '5': 's', '7': 't', '@': 'a', $: 's' };

/** Trims, collapses runs of white space and applies Unicode NFC, so the same word typed twice is the same string. */
export function tidyText(input: string): string {
  return input.normalize('NFC').replace(/\s+/gu, ' ').trim();
}

/** How many characters a reader sees (grapheme clusters, so an emoji or a letter with marks counts once). */
export function visibleLength(text: string): number {
  if (typeof Intl !== 'undefined' && 'Segmenter' in Intl) {
    let n = 0;
    for (const _ of new Intl.Segmenter(undefined, { granularity: 'grapheme' }).segment(text)) n++;
    return n;
  }
  return Array.from(text).length;
}

/** Splits into words on white space. */
export function wordsOf(text: string): string[] {
  const t = tidyText(text);
  return t ? t.split(' ') : [];
}

/**
 * The form used for matching, never for showing: lowercase, no accents or
 * combining marks (Latin accents, Hebrew points, Arabic short vowels), the
 * common letter swaps folded, and spelled-out letters joined.
 */
export function foldText(input: string): string {
  const base = input
    .normalize('NFKD')
    .replace(/\p{M}+/gu, '')
    .toLowerCase()
    .replace(/[013457@$]/g, (c) => SWAPS[c] as string);
  // "b a d", "b.a.d", "b-a-d" → "bad": three or more single letters in a row.
  const joined = base.replace(
    /(?<![\p{L}\p{N}])\p{L}(?:[\s.\-_*]+\p{L})(?:[\s.\-_*]+\p{L})+(?![\p{L}\p{N}])/gu,
    (run) => run.replace(/[\s.\-_*]+/g, ''),
  );
  return joined
    .replace(/[^\p{L}\p{N}\s]+/gu, ' ')
    .replace(/\s+/gu, ' ')
    .trim();
}

const LINK =
  /(?:https?:\/\/|www\.)\S+|\b[\p{L}\p{N}-]+\.(?:com|net|org|io|co|me|ly|gg|app|dev|info|xyz|tv|link|site|online)\b/iu;
// Matched per word and anchored, with classes that cannot overlap, so a long
// run of one character costs linear time, not quadratic.
const EMAIL_WORD = /^[^@]+@[^@.]+(?:\.[^@.]+)+$/u;
const hasEmail = (text: string) => text.split(' ').some((word) => EMAIL_WORD.test(word));
// Seven or more digits, allowing the usual separators (spaces, dots,
// dashes, brackets, a leading plus) between them. A single pass, so no input
// can make it slow.
const PHONE_SEPARATORS = new Set([' ', '\t', '\n', '(', ')', '.', '-', '+']);
function hasPhone(text: string): boolean {
  let digits = 0;
  for (const ch of text) {
    if (ch >= '0' && ch <= '9') {
      digits += 1;
      if (digits >= 7) return true;
    } else if (!PHONE_SEPARATORS.has(ch)) {
      digits = 0;
    }
  }
  return false;
}

/** Runs every rule and says the first one the text breaks. */
export function checkText(input: string, rules: TextRules = {}): TextCheck {
  const {
    maxLength = 200,
    maxWords = Number.POSITIVE_INFINITY,
    blocklist,
    allowLinks = false,
    allowContact = false,
  } = rules;
  const text = tidyText(input);
  if (!text) return { ok: false, reason: 'empty' };
  if (visibleLength(text) > maxLength) return { ok: false, reason: 'too-long' };
  if (!allowContact && (hasEmail(text) || hasPhone(text))) return { ok: false, reason: 'contact' };
  if (!allowLinks && LINK.test(text)) return { ok: false, reason: 'link' };
  if (blocklist && blocklist.length > 0 && isBlocked(text, blocklist)) return { ok: false, reason: 'blocked' };
  if (wordsOf(text).length > maxWords) return { ok: false, reason: 'too-many-words' };
  return { ok: true, text };
}

/**
 * True when any whole word, or run of words, of `text` is on the list.
 * Letters spelled out with spaces ("b a d") fold back into a word anywhere in
 * the text. Other splits ("ba d") are caught only when they are the whole
 * text, so a moderation queue still matters for open text.
 */
export function isBlocked(text: string, blocklist: readonly string[]): boolean {
  const hay = ` ${foldText(text)} `;
  const squeezed = ` ${hay.replace(/\s+/g, '')} `;
  for (const raw of blocklist) {
    const needle = foldText(raw);
    if (!needle) continue;
    if (hay.includes(` ${needle} `)) return true;
    // The whole text is the word with its spaces taken out ("ba d").
    if (!needle.includes(' ') && squeezed === ` ${needle} `) return true;
  }
  return false;
}

/**
 * @interlace/ui — text-safety-model
 *
 * The checks a short piece of typed text passes before a room shows it on a
 * shared screen: a word for a word cloud, a question for a Q&A board, a line
 * for an open wall. Pure, so the phone that sends it and the server that
 * receives it run the same rules and agree on the reason.
 *
 * ## What it checks, in order
 *
 *   1. empty            nothing left after trimming
 *   2. too-long         more than `maxLength` characters (counted as the reader sees them)
 *   3. contact          an email address or a phone number
 *   4. link             a URL or a bare domain
 *   5. blocked          a word on the consumer's `blocklist`
 *   6. too-many-words   more than `maxWords` words
 *
 * `blocked` comes before the word count, so "b a d" is refused for what it
 * says, not for having three words.
 *
 * Interlace ships no word list of its own: what is unwelcome depends on the
 * room, its language and its audience, so the consumer passes one. Matching
 * runs on `foldText`, which lowercases, strips accents and marks, folds the
 * common letter swaps (0→o, 1→i, 3→e, 4→a, 5→s, 7→t, @→a, $→s) and joins
 * letters spelled out with spaces or dots ("b a d" → "bad"), so the usual
 * dodges do not get through. Whole words only: a blocked word inside a
 * longer, innocent word is not a match.
 *
 * A filter is one layer, never the only one. Rooms that show typed text to
 * a crowd should also hold it for review (see `question-board-model`).
 */
